class TxtReaderPage extends StatefulWidget {
  final String bookTitle;
  final String txtPath;
  final String category;
  final String stampKey;
  final String? format;
  final List<String>? headings;

  const TxtReaderPage({
    super.key,
    required this.bookTitle,
    required this.txtPath,
    required this.category,
    required this.stampKey,
    this.format,
    this.headings,
  });

  @override
  _TxtReaderPageState createState() => _TxtReaderPageState();
}

