  bool get _isAPA => widget.format?.toUpperCase() == 'APA';

  TextStyle get _apaTextStyle => const TextStyle(
        fontFamily: 'Times New Roman',
        fontSize: 12,
        height: 2.0,
        color: Colors.black,
      );

  String _normalizeWord(String word) {
    return word
        .toLowerCase()
        .replaceAll(RegExp(r'[‐-–—−]'), '-')
        .replaceAll(RegExp(r'[^\w\s\-£$€¥]'), '') // ✅ Soporte para £
        .trim();
  }

  TextStyle get _apaHeadingStyle => const TextStyle(
        fontFamily: 'Times New Roman',
        fontSize: 16,
        fontWeight: FontWeight.bold,
        height: 2.0,
        color: Colors.black,
      );

  final Set<String> _unlocked = {};
  bool _bookStampUnlocked = false;

  String get _bookLockDocId =>
      widget.bookTitle.replaceAll(' ', '_').toLowerCase();

