  bool _shouldBeBold(String word) {
    // Eliminamos la restricción de categoría si se desea que las negritas funcionen siempre
    // o la mantenemos si es específica de Articles.
    // El problema principal era la comparación exacta.
    final normalized = _normalizeWord(word);
    return _articleBoldWords.any(
      (w) => _normalizeWord(w) == normalized,
    );
  }

