  Map<String, List<String>> _keysByFirstLetter = {};

  @override
  void initState() {
    super.initState();
    
    // ✅ CORRECCIÓN: Asegurar que todas las claves se normalicen para la búsqueda
    // y se ordenen por longitud descendente para encontrar frases largas primero.
    final allKeys = {
      ..._wordTranslations.keys,
      ..._articleBoldWords,
      for (var cat in _stampImages.keys) ..._stampImages[cat]!.keys,
    }.toList()
      ..sort((a, b) => b.length.compareTo(a.length));

    _keysByFirstLetter = {};
    for (var key in allKeys) {
      if (key.trim().isEmpty) continue;
      // Usamos la primera letra del texto original para el mapa
      String firstChar = key.trim()[0].toLowerCase();
      _keysByFirstLetter.putIfAbsent(firstChar, () => []).add(key);
    }

    _loadText();
    _confettiController =
        ConfettiController(duration: const Duration(seconds: 2));
    _loadUnlockedFromFirebase();
  }

  @override
  void dispose() {
    _confettiController.dispose();
    super.dispose();
  }

  bool _isNearEnd = false;

  Future<void> _loadText() async {
    String text = await rootBundle.loadString(widget.txtPath);

    if (_isAPA && widget.headings != null) {
      for (final h in widget.headings!) {
        final pattern = RegExp(
          r'(^|\n)\s*' + RegExp.escape(h) + r'\s*(?=\n)',
          caseSensitive: false,
        );
        text = text.replaceAllMapped(pattern, (m) {
          return '\n[[H]]$h[[/H]]\n';
        });
      }
    }

    final normalizedText = _normalizeWord(text);
    final stampNorm = _normalizeWord(widget.stampKey);

    _stampTotalOccurrences = RegExp(
      RegExp.escape(stampNorm),
    ).allMatches(normalizedText).length;

    _lastStampIndex = normalizedText.lastIndexOf(stampNorm);

    final newPages = _splitTextIntoPages(text);
    setState(() {
      _pages = newPages;
      // ✅ FIX: Clamp _currentPage para evitar RangeError si el índice guardado
      // supera el número real de páginas generadas.
      if (_pages.isNotEmpty && _currentPage >= _pages.length) {
        _currentPage = _pages.length - 1;
      }
    });
  }

  List<String> _splitTextIntoPages(String text) {
    final normalized = text.replaceAll('\r\n', '\n');
    final paragraphs = normalized
        .split(RegExp(r'\n\s*\n'))
        .map((p) => p.trim())
        .where((p) => p.isNotEmpty)
        .toList();

    const int maxCharsPerPage = 1200;
    List<String> pages = [];
    String buffer = '';

    for (final paragraph in paragraphs) {
      if ((buffer.length + paragraph.length) > maxCharsPerPage) {
        if (buffer.isNotEmpty) {
          pages.add(buffer.trim());
          buffer = '';
        }
      }
      buffer += '$paragraph\n\n';
    }
    if (buffer.isNotEmpty) {
      pages.add(buffer.trim());
    }
    return pages;
  }

  Future<void> _loadUnlockedFromFirebase() async {
    final uid = _auth.currentUser?.uid ?? 'anonymous';
    _unlocked.clear();

    // ✅ CORRECCIÓN: Cargar stamps de TODAS las categorías para evitar desbloqueos duplicados
    for (final category in _stampImages.keys) {
      final snap = await _db
          .collection('users')
          .doc(uid)
          .collection('stamps')
          .doc(category)
          .collection('items')
          .get();

      for (final doc in snap.docs) {
        _unlocked.add("$category|${doc.id}");
      }
    }

    final lockSnap = await _db
        .collection('users')
        .doc(uid)
        .collection('book_locks')
        .doc(_bookLockDocId)
        .get();

    _bookStampUnlocked = lockSnap.exists;
    if (mounted) setState(() {});
  }

  Future<void> _unlockStampFirebase(String word, String category) async {
    final uid = _auth.currentUser?.uid ?? 'anonymous';
    await _db
        .collection('users')
        .doc(uid)
        .collection('stamps')
        .doc(category)
        .collection('items')
        .doc(word)
        .set({
      'category': category,
      'word': word,
      'unlocked': true,
      'timestamp': FieldValue.serverTimestamp(),
    });

    // ✅ CORRECCIÓN: Actualizar estado local y llamar a setState
    setState(() {
      _unlocked.add("$category|$word");
    });
  }

  Future<void> _lockBook() async {
    final uid = _auth.currentUser?.uid ?? 'anonymous';
    await _db
        .collection('users')
        .doc(uid)
        .collection('book_locks')
        .doc(_bookLockDocId)
        .set({'locked': true});

    setState(() {
      _bookStampUnlocked = true;
    });
  }

  void _handleWordTap(String word) {
    final tapped = _normalizeWord(word);
    final stampKeyNorm = _normalizeWord(widget.stampKey);

    print("--- DEBUG STAMP ---");
    print("Palabra tapeada: '$word' (Normalizada: '$tapped')");
    print(
        "StampKey del libro: '${widget.stampKey}' (Normalizada: '$stampKeyNorm')");
    print("Categoría del libro: '${widget.category}'");

    // 1️⃣ MOSTRAR TRADUCCIÓN
    String? translationKey;
    for (var k in _wordTranslations.keys) {
      if (_normalizeWord(k) == tapped) {
        translationKey = k;
        break;
      }
    }

    if (translationKey != null) {
      _showTranslationBottomSheet(translationKey);
    }

    // 2️⃣ VERIFICAR SI ES LA STAMP DEL LIBRO
    if (tapped != stampKeyNorm) {
      print("No es la stamp del libro.");
      return;
    }

    // 3️⃣ BÚSQUEDA GLOBAL DE LA STAMP
    String? foundCategory;
    String? foundOriginalKey;
    String? foundImagePath;

    // Primero buscamos en la categoría actual
    final currentCatStamps = _stampImages[widget.category];
    if (currentCatStamps != null) {
      for (var k in currentCatStamps.keys) {
        if (_normalizeWord(k) == tapped) {
          foundCategory = widget.category;
          foundOriginalKey = k;
          foundImagePath = currentCatStamps[k];
          break;
        }
      }
    }

    // Si no se encontró, buscamos en TODAS las categorías
    if (foundOriginalKey == null) {
      for (var cat in _stampImages.keys) {
        final stamps = _stampImages[cat]!;
        for (var k in stamps.keys) {
          if (_normalizeWord(k) == tapped) {
            foundCategory = cat;
            foundOriginalKey = k;
            foundImagePath = stamps[k];
            break;
          }
        }
        if (foundOriginalKey != null) break;
      }
    }

    if (foundOriginalKey == null ||
        foundImagePath == null ||
        foundCategory == null) {
      return;
    }

    // ✅ CORRECCIÓN: Verificar si ya está desbloqueada antes de proceder
    if (_unlocked.contains("$foundCategory|$foundOriginalKey")) {
      print("ℹ️ La stamp ya estaba desbloqueada.");
      return;
    }

    _unlockStampFirebase(foundOriginalKey, foundCategory);

    // 4️⃣ BLOQUEAR LIBRO
    if (!_bookStampUnlocked) {
      final bool appearsOnlyOnce = _stampTotalOccurrences == 1;
      if (tapped == 'he' && !_isNearEnd && !appearsOnlyOnce) {
        print("🔒 Regla 'he': No se bloquea el libro aún.");
      } else if (_isNearEnd || appearsOnlyOnce) {
        _lockBook();
        print("🔒 Libro bloqueado correctamente.");
      }
    }

    _showStampUnlockedPopup(foundOriginalKey, foundImagePath, foundCategory);
  }

  void _showTranslationBottomSheet(String word) {
    showModalBottomSheet(
      context: context,
      backgroundColor: Colors.transparent,
      isScrollControlled: true,
      builder: (_) => Container(
        width: double.infinity,
        constraints: BoxConstraints(
          maxHeight: MediaQuery.of(context).size.height * 0.35,
        ),
        padding: const EdgeInsets.fromLTRB(20, 12, 20, 24),
        decoration: const BoxDecoration(
          color: Colors.white,
          borderRadius: BorderRadius.vertical(
            top: Radius.circular(24),
          ),
        ),
        child: SingleChildScrollView(
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.center,
            children: [
              // Indicador
              Container(
                width: 40,
                height: 4,
                margin: const EdgeInsets.only(bottom: 16),
                decoration: BoxDecoration(
                  color: Colors.black26,
                  borderRadius: BorderRadius.circular(2),
                ),
              ),

              // Palabra original (nunca overflow)
              Text(
                word,
                textAlign: TextAlign.center,
                softWrap: true,
                overflow: TextOverflow.visible,
                style: const TextStyle(
                  fontSize: 26,
                  fontWeight: FontWeight.bold,
                  color: Colors.black,
                ),
              ),

              const SizedBox(height: 12),

              // Traducción (scroll automático si es larga)
              Text(
                _wordTranslations[word] ?? "No translation",
                textAlign: TextAlign.center,
                softWrap: true,
                overflow: TextOverflow.visible,
                style: const TextStyle(
                  fontSize: 22,
                  fontWeight: FontWeight.w600,
                  color: Colors.black,
                  height: 1.35,
                ),
              ),

              const SizedBox(height: 24),

              const Text(
                "Swipe down to close",
