  void _showStampUnlockedPopup(String word, String imagePath, String category) {
    _confettiController.play();
    showDialog(
      context: context,
      builder: (_) => AlertDialog(
        title: const Text("You unlocked this stamp! 🎉"),
        content: Image.asset(imagePath, height: 150),
        actions: [
          TextButton(
            onPressed: () {
              _confettiController.stop();
              Navigator.pop(context);
            },
            child: const Text("OK"),
          )
        ],
      ),
    );
  }

  bool _isBoundaryChar(String? ch) =>
      ch == null || RegExp(r'[\s\W]').hasMatch(ch);

  bool _isAnyStampWord(String word) {
    final w = _normalizeWord(word);
    for (var cat in _stampImages.keys) {
      if (_stampImages[cat]!.keys.any((k) => _normalizeWord(k) == w)) {
        return true;
      }
    }
    return false;
  }

  bool _hasTranslation(String word) {
    final w = _normalizeWord(word);
    for (var k in _wordTranslations.keys) {
      if (_normalizeWord(k) == w) return true;
    }
    return false;
  }

  List<TextSpan> _buildTextSpans(String text) {
    if (text.isEmpty) return [];

    final spans = <TextSpan>[];
    int pos = 0;
    StringBuffer normalTextBuffer = StringBuffer();

    while (pos < text.length) {
      String? bestMatch;
      String charAtPos = text[pos].toLowerCase();

      final potentialKeys = _keysByFirstLetter[charAtPos];

      if (potentialKeys != null) {
        for (final key in potentialKeys) {
          if (pos + key.length <= text.length) {
            final slice = text.substring(pos, pos + key.length);
            if (slice.toLowerCase() == key.toLowerCase()) {
              final prev = pos > 0 ? text[pos - 1] : null;
              final next = pos + key.length < text.length
                  ? text[pos + key.length]
                  : null;

              bool isCurrency = RegExp(r'[£$€¥]').hasMatch(key);
              if ((isCurrency || _isBoundaryChar(prev)) &&
                  (isCurrency || _isBoundaryChar(next))) {
                bestMatch = key;
                break;
              }
            }
          }
        }
      }

      if (bestMatch != null) {
        if (normalTextBuffer.isNotEmpty) {
          spans.add(TextSpan(
              text: normalTextBuffer.toString(),
              style: const TextStyle(color: Colors.black)));
          normalTextBuffer.clear();
        }

        final slice = text.substring(pos, pos + bestMatch.length);
        final bool isAnyStamp = _isAnyStampWord(bestMatch);
        final bool hasTrans = _hasTranslation(bestMatch);
        final bool forceBold = _shouldBeBold(bestMatch);
        final bool isStampKeyWord =
            _normalizeWord(bestMatch) == _normalizeWord(widget.stampKey);

        // ✅ Si tiene traducción o es stamp, debe ser azul
        final bool shouldBeBlue = isAnyStamp || hasTrans;

        spans.add(
          TextSpan(
            text: slice,
            style: TextStyle(
              color: isStampKeyWord
                  ? Colors.blue.shade900
                  : (shouldBeBlue ? Colors.blue : Colors.black),
              fontWeight: (forceBold || isStampKeyWord)
                  ? FontWeight.bold
                  : (shouldBeBlue ? FontWeight.w600 : FontWeight.normal),
            ),
            recognizer: TapGestureRecognizer()
              ..onTap = () => _handleWordTap(slice),
          ),
        );
        pos += bestMatch.length;
      } else {
        normalTextBuffer.write(text[pos]);
        pos++;
      }
    }

    if (normalTextBuffer.isNotEmpty) {
      spans.add(TextSpan(
          text: normalTextBuffer.toString(),
          style: const TextStyle(color: Colors.black)));
    }

    return spans;
  }

  List<Widget> _buildApaPage(String text) {
    final lines = text.split('\n');
    List<Widget> widgets = [];

    for (var line in lines) {
      if (line.trim().isEmpty) continue;

      if (line.contains('[[H]]')) {
        final headingText =
            line.replaceAll('[[H]]', '').replaceAll('[[/H]]', '');
        widgets.add(
          Padding(
            padding: const EdgeInsets.symmetric(vertical: 24),
            child: Text(
              headingText,
              style: _apaHeadingStyle,
              textAlign: TextAlign.center,
            ),
          ),
        );
        continue;
      }

      widgets.add(
        Padding(
          padding: const EdgeInsets.only(bottom: 12),
          child: RichText(
            textAlign: TextAlign.left,
            text: TextSpan(
              style: _apaTextStyle,
              children: [
                const TextSpan(text: "     "),
                ..._buildTextSpans(line),
              ],
            ),
          ),
        ),
      );
    }
    return widgets;
  }

  void _checkIfNearEnd() {
    if (_pages.isEmpty) return;
    if (_currentPage >= (_pages.length * 0.9).floor()) {
      _isNearEnd = true;
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text(
          _bookStampUnlocked ? "You completed this book 🎉" : widget.bookTitle,
        ),
      ),
      body: _pages.isEmpty
          ? const Center(child: CircularProgressIndicator())
          : Padding(
              padding: const EdgeInsets.all(16),
              child: Column(
                children: [
                  Expanded(
                    child: SingleChildScrollView(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          if (_isAPA)
                            ..._buildApaPage(_pages[_currentPage])
                          else
                            RichText(
                              text: TextSpan(
                                style: const TextStyle(
                                    fontSize: 18, color: Colors.black),
                                children: _buildTextSpans(_pages[_currentPage]),
                              ),
                            ),
                        ],
                      ),
                    ),
                  ),
                  Row(
                    mainAxisAlignment: MainAxisAlignment.spaceBetween,
                    children: [
                      IconButton(
                        icon: const Icon(Icons.arrow_back),
                        onPressed: _currentPage > 0
                            ? () => setState(() {
                                  _currentPage--;
                                  _checkIfNearEnd();
                                })
                            : null,
                      ),
                      Text("${_currentPage + 1} / ${_pages.length}"),
                      IconButton(
                        icon: const Icon(Icons.arrow_forward),
                        onPressed: _currentPage < _pages.length - 1
                            ? () => setState(() {
                                  _currentPage++;
                                  _checkIfNearEnd();
                                })
                            : null,
                      ),
                    ],
                  ),

                  // ── Continue to Quiz button (solo en la última página) ──
                  if (_pages.isNotEmpty &&
                      _currentPage == _pages.length - 1)
                    Padding(
                      padding: const EdgeInsets.only(top: 16, bottom: 8),
                      child: Center(
                        child: _ContinueToQuizButton(
                          category: widget.category,
                          onTap: () {
                            Navigator.push(
                              context,
                              PageRouteBuilder(
                                pageBuilder: (_, anim, __) =>
                                    BookQuizPage(bookTitle: widget.bookTitle),
                                transitionsBuilder: (_, anim, __, child) =>
                                    FadeTransition(opacity: anim, child: child),
                                transitionDuration:
                                    const Duration(milliseconds: 600),
                              ),
                            );
                          },
                        ),
                      ),
                    ),
                ],
              ),
            ),
    );
  }
}

// ─────────────────────────────────────────────────────────────────────────────
//  CONTINUE BUTTON  (space-green glow style)
// ─────────────────────────────────────────────────────────────────────────────

class _ContinueToQuizButton extends StatefulWidget {
  final VoidCallback onTap;
  final String category;

  const _ContinueToQuizButton({
    required this.onTap,
    required this.category,
  });

  @override
  State<_ContinueToQuizButton> createState() => _ContinueToQuizButtonState();
}

class _ContinueToQuizButtonState extends State<_ContinueToQuizButton>
    with SingleTickerProviderStateMixin {
  late final AnimationController _ctrl;
  late final Animation<double> _glow;

  // ── Colores por categoría (mismos que BookQuizPage) ──────────────────────
  Color get _accent {
    switch (widget.category.toLowerCase()) {
      case 'biography':
        return const Color(0xFFFFD700); // Amarillo
      case 'news':
        return const Color(0xFF39FF7A); // Verde
      case 'stories':
        return const Color(0xFF38B6FF); // Azul
      case 'articles':
        return const Color(0xFFB06AFF); // Morado
      default:
        return const Color(0xFF39FF7A); // Verde fallback
    }
  }

  Color get _gradientDark => Color.lerp(_accent, Colors.black, 0.65)!;
  Color get _gradientDarker => Color.lerp(_accent, Colors.black, 0.80)!;

  @override
  void initState() {
    super.initState();
    _ctrl = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 1400),
    )..repeat(reverse: true);
    _glow = Tween<double>(begin: 0.55, end: 1.0).animate(
      CurvedAnimation(parent: _ctrl, curve: Curves.easeInOut),
    );
  }

  @override
  void dispose() {
    _ctrl.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final accent = _accent;
    final dark = _gradientDark;
    final darker = _gradientDarker;

    return AnimatedBuilder(
      animation: _glow,
      builder: (_, __) => GestureDetector(
        onTap: widget.onTap,
        child: Container(
          padding: const EdgeInsets.symmetric(horizontal: 36, vertical: 15),
          decoration: BoxDecoration(
            gradient: LinearGradient(
              colors: [dark, darker],
            ),
            borderRadius: BorderRadius.circular(50),
            boxShadow: [
              BoxShadow(
                color: accent.withOpacity(_glow.value * 0.5),
                blurRadius: 22,
                spreadRadius: 3,
                offset: const Offset(0, 4),
              ),
            ],
            border: Border.all(
              color: accent.withOpacity(0.6),
              width: 1.5,
            ),
          ),
          child: Row(
            mainAxisSize: MainAxisSize.min,
            children: [
              Icon(Icons.auto_awesome, color: accent, size: 20),
              const SizedBox(width: 10),
              const Text(
                'Continue',
                style: TextStyle(
                  color: Colors.white,
                  fontSize: 17,
                  fontWeight: FontWeight.bold,
                  letterSpacing: 0.5,
                ),
              ),
              const SizedBox(width: 10),
              Icon(Icons.arrow_forward_rounded, color: accent, size: 20),
            ],
          ),
        ),
      ),
    );
  }
}